import {openLogin} from './auth.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let account=undefined,generation=0,catalog=[],preferences=[],editing=null,next=null,busy=false,loading=false,alertsEnabled=true;
const say=(text,error=false)=>{$('#pref-status').textContent=text;$('#pref-status').dataset.error=error};
async function api(path,method='GET',body){const r=await fetch('/api/user/'+path,{method,credentials:'same-origin',headers:body?{'content-type':'application/json'}:{},...(body?{body:JSON.stringify(body)}:{}),signal:AbortSignal.timeout(20000)});const data=await r.json();if(!r.ok)throw Error(data.error||'请求失败，请稍后重试');return data}
function badge(n){const el=$('#portal-alert-count');if(!el)return;el.textContent=n>99?'99+':n;el.hidden=!n;$('#pref-unread').textContent=n+' 条未读'}
function fields(type,values){const item=catalog.find(c=>c.id===type),names=item?.slotNames??[];$('#pref-holes').innerHTML='<option value="">不限孔数</option>'+Array.from({length:names.length+1},(_,i)=>`<option value="${i}">${i} 孔</option>`).join('');$('#pref-ranges').innerHTML=names.map((name,i)=>`<div class="pref-range"><span>第${i+1}孔 · ${esc(name)}</span><label>最小值<input data-range="${i}" data-side="min" type="number" min="0" max="999999" step="1" placeholder="不限" value="${esc(values?.[i]?.min??'')}" /></label><label>最大值<input data-range="${i}" data-side="max" type="number" min="0" max="999999" step="1" placeholder="不限" value="${esc(values?.[i]?.max??'')}" /></label></div>`).join('')}
function reset(){editing=null;$('#pref-form').reset();fields($('#pref-type').value);$('#pref-form-title').textContent='新增抽签偏好';$('#pref-save').textContent='保存并检查'}
function inputValue(){const type=$('#pref-type').value,item=catalog.find(c=>c.id===type);if(!item)throw Error('请选择谪星外观');const number=el=>el.value===''?null:Number(el.value),money=el=>el.value===''?null:Math.round(Number(el.value)*100);return {type,name:$('#pref-name').value,holes:$('#pref-holes').value===''?null:Number($('#pref-holes').value),ranges:item.slotNames.map((_,i)=>({min:number($(`[data-range="${i}"][data-side=min]`)),max:number($(`[data-range="${i}"][data-side=max]`))})),priceMin:money($('#pref-price-min')),priceMax:money($('#pref-price-max')),wechat:$('#pref-wechat').checked,enabled:$('#pref-enabled').checked}}
const yuan=cents=>cents===null?'不限':'¥'+(Number(cents)/100).toLocaleString('zh-CN',{maximumFractionDigits:2}),time=value=>new Date(value).toLocaleString('zh-CN',{hour12:false});
function renderPreferences(){
 $('#pref-count').textContent=preferences.length+' / 20';$('#pref-list').innerHTML=preferences.length?preferences.map(p=>`<article class="preference-row"><strong>${esc(p.name)} · ${p.enabled?'启用中':'已暂停'}</strong><p>${esc(p.criteria.skin)} · ${p.criteria.holes===null?'不限孔数':p.criteria.holes+'孔'} · ${yuan(p.criteria.priceMin)} ～ ${yuan(p.criteria.priceMax)}</p><p>${p.criteria.ranges.map((r,i)=>r.min===null&&r.max===null?'':`第${i+1}孔 ${r.min??'不限'}～${r.max??'不限'}`).filter(Boolean).join('；')||'星格数值不限'} · ${p.wechat?'站内＋微信':'站内消息'}</p><div class="pref-row-actions"><button type="button" data-edit="${p.id}">编辑</button><button type="button" data-toggle="${p.id}">${p.enabled?'暂停':'启用'}</button><button type="button" data-delete="${p.id}">删除</button></div></article>`).join(''):'<p class="pref-empty">还没有抽签偏好，先选一个喜欢的谪星。</p>';
}
function renderMessages(rows,append=false){const html=rows.map(m=>{const p=m.payload,active=Date.parse(p.lotteryEndsAt)>Date.now();let url='';try{const u=new URL(p.url);if(u.protocol==='https:'&&u.hostname==='yjwujian.cbg.163.com')url=u.href}catch{}return `<article class="preference-message" data-unread="${!m.read_at}"><strong>${esc(p.name)} · ${esc(p.skin)}</strong><p class="pref-price">${yuan(p.priceCents)} <small>· ${p.holesCount}孔</small></p><p>星格 ${p.slots.map((s,i)=>p.unlocks[i]===1?s:'未解锁').join(' / ')}<br>抽签截止 ${esc(time(p.lotteryEndsAt))}${active?'':' · 已截止'}<br>观察于 ${esc(time(p.observedAt))}</p><p>微信：${esc(({'not-requested':'未开启',pending:'等待发送',accepted:'微信接口已接收',failed:'发送失败',expired:'已过期',cancelled:'偏好已停用',limited:'本日额度已用完',uncertain:'发送结果待核实'})[m.wechat_status]||'待核验')}</p><div class="pref-row-actions">${!m.read_at?`<button type="button" data-read="${m.id}">标记已读</button>`:''}${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${active?'去藏宝阁核验当前状态 ↗':'查看原商品 ↗'}</a>`:''}</div></article>`}).join('');const el=$('#pref-messages');if(append)el.insertAdjacentHTML('beforeend',html);else el.innerHTML=html||'<p class="pref-empty">暂无匹配消息。只检查65分钟内观察到、已确认且未截止的抽签商品。</p>'}
async function load(append=false){if(!account||loading)return;loading=true;const version=generation;try{const [saved,inbox]=await Promise.all([api('preferences'),api('messages'+(append&&next?'?before='+next:''))]);if(version!==generation)return;preferences=saved.preferences;renderPreferences();renderMessages(inbox.messages,append);next=inbox.next;$('#pref-more').hidden=!next;badge(inbox.unread);$('#pref-wechat').disabled=!saved.notificationReady;$('#pref-wechat-help').textContent=saved.notificationReady?'开启后，符合条件的抽签商品会发送微信模板提醒；每个账号每日最多3条。':'微信模板提醒尚未配置，站内消息可正常使用。';say('仅抽签 · 账号云端保存 · 自动采集约每30分钟运行，可能延迟。')}catch(e){if(version===generation)say(e.message,true)}finally{loading=false}}
async function mutate(action){if(busy)return;busy=true;const version=generation;$('#pref-save').disabled=true;try{await action();if(version!==generation)return;await load();say('设置已更新。只提醒抽签中的商品。')}catch(e){if(version===generation)say(e.message,true)}finally{busy=false;$('#pref-save').disabled=false}}
if($('#pref-form')){
$('#pref-login').onclick=()=>openLogin();$('#pref-type').onchange=()=>fields($('#pref-type').value);$('#pref-reset').onclick=reset;
$('#pref-form').onsubmit=e=>{e.preventDefault();if(!account)return;mutate(async()=>{const result=await api('preferences'+(editing?'?id='+editing:''),'PUT',inputValue());reset();say('已保存，新增 '+result.created+' 条匹配消息')})};
$('#pref-list').onclick=e=>{const button=e.target.closest('button');if(!button||busy)return;const p=preferences.find(p=>p.id===(button.dataset.edit||button.dataset.toggle||button.dataset.delete));if(!p)return;if(button.dataset.edit){editing=p.id;$('#pref-name').value=p.name;$('#pref-type').value=p.criteria.type;fields(p.criteria.type,p.criteria.ranges);$('#pref-holes').value=p.criteria.holes??'';$('#pref-price-min').value=p.criteria.priceMin===null?'':p.criteria.priceMin/100;$('#pref-price-max').value=p.criteria.priceMax===null?'':p.criteria.priceMax/100;$('#pref-enabled').checked=p.enabled;$('#pref-wechat').checked=p.wechat;$('#pref-form-title').textContent='编辑抽签偏好';$('#pref-save').textContent='保存修改';$('#pref-name').focus();return}if(button.dataset.delete){if(!confirm('删除此抽签偏好？历史消息仍会保留。'))return;mutate(async()=>{await api('preferences?id='+p.id,'DELETE');if(editing===p.id)reset()})}else mutate(()=>api('preferences?id='+p.id,'PUT',{...p.criteria,name:p.name,wechat:p.wechat,enabled:!p.enabled}))};
$('#pref-messages').onclick=e=>{const button=e.target.closest('[data-read]');if(button)mutate(()=>api('messages/read','POST',{id:button.dataset.read}))};$('#pref-read-all').onclick=()=>mutate(()=>api('messages/read','POST',{id:null}));$('#pref-more').onclick=()=>load(true);$('#pref-check').onclick=()=>mutate(()=>api('check','POST'));
window.addEventListener('auth-changed',async e=>{const id=e.detail.loggedIn?e.detail.user?.id:null;if(id===account)return;account=id;generation++;preferences=[];next=null;loading=false;$('#pref-account').hidden=!id;$('#pref-guest').hidden=!!id;$('#pref-check').disabled=!id;$('#pref-list').replaceChildren();$('#pref-messages').replaceChildren();badge(0);reset();if(!id){say('登录后，偏好与消息会跟随账号同步。');return}try{if(!catalog.length){const r=await fetch('/api/catalog');if(!r.ok)throw Error();catalog=(await r.json()).items;$('#pref-type').innerHTML='<option value="" disabled>请选择谪星</option>'+catalog.map(c=>`<option value="${esc(c.id)}">${esc(c.name)} · ${esc(c.owner)}</option>`).join('');$('#pref-type').value=''}await load()}catch{say('图鉴读取失败，请刷新后重试',true)}});
setInterval(()=>{if(account&&document.visibilityState==='visible'&&!busy)load()},60000);
window.addEventListener('account-settings-changed',e=>{alertsEnabled=e.detail.alerts_enabled;if(e.detail.loggedIn&&!alertsEnabled)say('全部账号偏好提醒已暂停，可在头像 → 设置中重新开启。')});
window.addEventListener('lottery-favorites-updated',()=>{if(account&&!busy)load()});
}
